import * as React from "react";
import { render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Link.stories";
import Link from ".";

const { Basic } = composeStories(stories) as any;

describe("Link component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("is a normal link with target blank", () => {
    const { container } = render(<Link target="_blank">Text</Link>);
    expect(container).toMatchSnapshot();
  });

  it("is a normal link with a provided id and an additional class", () => {
    const { container } = render(
      <Link className="test-classname" id="test-id">
        Text
      </Link>
    );
    expect(container).toMatchSnapshot();
  });

  it("passes through props", () => {
    render(
      <Link data-testid="link" href="#">
        Text
      </Link>
    );
    expect(screen.getByRole("link")).toHaveAttribute("data-testid", "link");
  });
});
